// ============================================================================
// 2. Préparer les sources (auto)
// ----------------------------------------------------------------------------
// Lit la config sortie par le nœud "Configurer le sujet" et émet un item par
// source à télécharger, en y embarquant les URLs déjà publiées aujourd'hui
// (anti-doublon entre runs).
// ============================================================================

const config = $items('Configurer le sujet')[0]?.json || {};
const sameDayResponse = $input.first()?.json || {};
const sameDayUrls = Array.isArray(sameDayResponse.urls) ? sameDayResponse.urls : [];

return (config.sources || []).map((source) => ({
  json: {
    ...source,
    sameDayUrls,
    topic: config.topic,
    blog: config.blog,
    gemini: config.gemini,
    runDate: config.runDate
  }
}));

// ============================================================================
// 3. Assembler le récap (auto)
// ----------------------------------------------------------------------------
// Lit la config + tous les flux téléchargés, parse le XML/RSS/Atom, applique
// les filtres positifs/négatifs et l'âge max, dédoublonne et construit :
//   - le prompt Gemini (orienté édito, pas admin),
//   - un récap fallback prêt à publier sans IA (lead + 2-3 phrases courtes,
//     zéro mention "France : X articles", zéro mention "Sources à vérifier").
//
// Sortie unique : { secret, fallbackTitle, fallbackSummary, recapDate,
//                   geminiModel, geminiApiKey, geminiRequest, postBase }
// ============================================================================

function decodeHtml(value = '') {
  return String(value)
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#038;/g, '&')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function pickRaw(block, tag) {
  const escapedTag = tag.replace(':', '\\:');
  const match = String(block || '').match(new RegExp(`<${escapedTag}[^>]*>([\\s\\S]*?)<\\/${escapedTag}>`, 'i'));
  return match?.[1] || '';
}

function pick(block, tag) {
  return decodeHtml(pickRaw(block, tag));
}

function cleanUrl(value) {
  const text = decodeHtml(value)
    .replace(/^url:\s*/i, '')
    .replace(/^link:\s*/i, '')
    .replace(/^guid:\s*/i, '')
    .replace(/^[\s"'<>]+|[\s"'<>]+$/g, '')
    .trim();
  const match = text.match(/https?:\/\/[^\s"'<>]+/i);
  return match ? match[0] : text;
}

function pickLink(block) {
  const href = String(block || '').match(/<link\b[^>]*\bhref=["']([^"']+)["'][^>]*\/?>/i)?.[1];
  return cleanUrl(href || pickRaw(block, 'link') || pickRaw(block, 'guid') || pickRaw(block, 'id'));
}

function stripSourceSuffix(title, sourceName) {
  return String(title || '')
    .replace(new RegExp(`\\s+-\\s+${String(sourceName || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}$`, 'i'), '')
    .replace(/\s+-\s+Google News$/i, '')
    .trim();
}

function normalizeUrl(value) {
  const raw = cleanUrl(value);
  const match = String(raw || '').match(/^https?:\/\/[^\s"'<>]+/i);
  if (!match) return '';
  return match[0].replace(/[?#].*$/, '').replace(/\/$/, '').toLowerCase();
}

function recapSlot(date) {
  const hour = date.getHours();
  if (hour < 8) return 'Dans la nuit';
  if (hour < 13) return 'Matinal';
  if (hour < 21) return 'Cet aprem';
  return 'Soir';
}

// On vérifie le filtre positif uniquement sur le contenu (titre + extrait),
// PAS sur le nom de la source : sinon n'importe quel article publié par
// "Dot Esports" ou "Esports Insider" passe automatiquement parce que le mot
// "esports" est dans le nom du média. Le négatif, lui, peut regarder large
// (titre + extrait + source) pour éviter une source-pourriel ciblée.
function isTopicArticle(article, topic) {
  const haystack = `${article.title} ${article.snippet}`.toLowerCase();
  const haystackWide = `${haystack} ${article.source || ''}`.toLowerCase();
  const publishedAt = new Date(article.publishedAt);
  if (!Number.isNaN(publishedAt.getTime())) {
    const maxAgeDays =
      article.method === 'google' ? topic.maxAgeDays.google : topic.maxAgeDays.rss;
    if (Date.now() - publishedAt.getTime() > maxAgeDays * 24 * 60 * 60 * 1000) return false;
  }
  if ((topic.negativeKeywords || []).some((term) => haystackWide.includes(term))) return false;
  if (!Array.isArray(topic.positiveKeywords) || topic.positiveKeywords.length === 0) return true;
  return topic.positiveKeywords.some((term) => haystack.includes(term));
}

function parseItems(xml, source, topic) {
  const text = String(xml || '');
  const matches = [
    ...text.matchAll(/<item[\s\S]*?>([\s\S]*?)<\/item>/gi),
    ...text.matchAll(/<entry[\s\S]*?>([\s\S]*?)<\/entry>/gi)
  ];

  return matches
    .map((match) => {
      const block = match[1];
      const rawTitle = pick(block, 'title');
      return {
        title: stripSourceSuffix(rawTitle, source.name),
        url: pickLink(block),
        source: source.name,
        region: source.region,
        method: source.method,
        publishedAt: pick(block, 'pubDate') || pick(block, 'updated') || pick(block, 'published'),
        snippet: decodeHtml(
          pickRaw(block, 'description') || pickRaw(block, 'content:encoded') || pickRaw(block, 'summary')
        )
      };
    })
    .filter((article) => article.title && article.url && isTopicArticle(article, topic))
    .slice(0, source.max || 10);
}

function resolveSource(item, index, preparedSources) {
  const pairedIndex = Array.isArray(item.pairedItem)
    ? item.pairedItem[0]?.item
    : item.pairedItem?.item;
  const prepared = preparedSources[pairedIndex ?? index]?.json || {};
  return { ...prepared, ...item.json };
}

function extractXml(json) {
  const candidates = [json.rss, json.data, json.body, json.response, json.text];
  const value = candidates.find((candidate) => typeof candidate === 'string' && candidate.trim());
  if (value) return value;
  if (typeof json === 'string') return json;
  return '';
}

function countBySource(list) {
  return list.reduce((acc, article) => {
    acc[article.source] = (acc[article.source] || 0) + 1;
    return acc;
  }, {});
}

function truncate(text, max) {
  const value = String(text || '').trim();
  if (value.length <= max) return value;
  return `${value.slice(0, Math.max(0, max - 1)).trimEnd()}…`;
}

// Fallback éditorial sans aucune info administrative.
// On part du principe qu'un humain qui voit ce résumé doit comprendre la news,
// pas le pipeline. Donc : pas de "France : X articles", pas de "Sources à vérifier",
// pas de "aucun article retenu". Les erreurs vont dans post.errors (caché).
function buildFallbackTitle(slot, topicLabel, leadArticle) {
  if (!leadArticle) return `${slot} - ${topicLabel}, créneau silencieux`;
  return `${slot} - ${truncate(leadArticle.title, 80)}`;
}

function buildFallbackSummary(selected, topicLabel) {
  if (!selected.length) {
    return `Pas de signal fort sur ${topicLabel} pour ce créneau. Le radar reprend dans quelques heures.`;
  }
  const titles = selected
    .slice(0, 4)
    .map((a) => String(a.title || '').replace(/[.;]+\s*$/, ''))
    .filter(Boolean);
  if (titles.length === 1) return `${titles[0]}.`;
  if (titles.length === 2) return `À la une : ${titles[0]}. En parallèle, ${titles[1]}.`;
  if (titles.length === 3) return `À la une : ${titles[0]}. En parallèle : ${titles[1]} ; ${titles[2]}.`;
  return `À la une : ${titles[0]}. En parallèle : ${titles[1]} ; ${titles[2]} ; ${titles[3]}.`;
}

const items = $input.all();
const preparedSources = $items('Preparer les sources');
const config = $items('Configurer le sujet')[0]?.json || {};
const topic = config.topic || { slug: 'esport', label: 'Esport', mode: 'fr-intl' };
const errors = [];
const loadedArticles = [];
const sameDayUrls = new Set(preparedSources[0]?.json?.sameDayUrls || []);

for (const [index, item] of items.entries()) {
  const source = resolveSource(item, index, preparedSources);
  const xml = extractXml(item.json);
  if (!xml || String(xml).length < 20) {
    errors.push(`${source.name || `Source ${index + 1}`}: réponse vide`);
    continue;
  }
  const parsed = parseItems(xml, source, topic);
  if (!parsed.length) errors.push(`${source.name}: aucun article ${topic.label} retenu`);
  loadedArticles.push(...parsed);
}

const seen = new Set();
let skippedInvalidUrl = 0;
let skippedDuplicate = 0;
let skippedSameDay = 0;
const articles = [];

for (const article of loadedArticles.sort(
  (a, b) => new Date(b.publishedAt || 0) - new Date(a.publishedAt || 0)
)) {
  const key = normalizeUrl(article.url);
  if (!key) {
    skippedInvalidUrl++;
    continue;
  }
  if (seen.has(key)) {
    skippedDuplicate++;
    continue;
  }
  seen.add(key);
  if (sameDayUrls.has(key)) {
    skippedSameDay++;
    continue;
  }
  articles.push(article);
  if (articles.length >= (topic.caps?.total || 36)) break;
}

const frArticles = articles.filter((a) => a.region === 'fr').slice(0, topic.caps?.fr || 14);
const intlArticles = articles.filter((a) => a.region !== 'fr').slice(0, topic.caps?.intl || 18);
const selectedArticles =
  topic.mode === 'fr'
    ? frArticles
    : topic.mode === 'intl'
    ? intlArticles
    : [...frArticles, ...intlArticles];

const sourceGroups = { fr: countBySource(frArticles), intl: countBySource(intlArticles) };
const hasBothRegions = topic.mode === 'fr-intl' && frArticles.length > 0 && intlArticles.length > 0;

const now = new Date();
const recapDate = now.toLocaleDateString('fr-FR', { dateStyle: 'long' });
const slot = recapSlot(now);
const leadArticle = selectedArticles[0] || frArticles[0] || intlArticles[0] || null;

const fallbackTitle = buildFallbackTitle(slot, topic.label, leadArticle);
const fallbackSummary = buildFallbackSummary(selectedArticles, topic.label);

const articleLines = selectedArticles
  .slice(0, 28)
  .map((article, index) => {
    const snippet = article.snippet ? ` | contexte : ${article.snippet.slice(0, 260)}` : '';
    const tag = article.region === 'fr' ? 'FR' : 'INT';
    return `${index + 1}. [${tag}] ${article.source} - ${article.title}${snippet}`;
  })
  .join('\n');

// Cadre stylistique côté régions : en mode mixte avec articles FR ET INT,
// on autorise un "côté français" / "à l'international" glissé dans une phrase,
// MAIS jamais en chiffres, jamais en bandeau, jamais comme tête de chapitre.
const styleGuide =
  topic.mode === 'fr-intl' && hasBothRegions
    ? "Les articles mêlent France et international ; tu peux glisser \"côté français\" ou \"à l'international\" dans une phrase si ça aide la lecture, mais jamais en titre de paragraphe, jamais avec des chiffres."
    : topic.mode === 'fr'
    ? "Tous les articles sont francophones. N'introduis aucune mention \"France\", \"FR\" ou \"international\"."
    : topic.mode === 'intl'
    ? "Tous les articles sont internationaux. N'introduis aucune mention \"France\", \"FR\" ou \"international\"."
    : "Adopte une formulation globale, sans découpage régional.";

// Prompt orienté édito : zéro mention chiffres, zéro mention "sources",
// zéro mention "aucun article retenu". Le titre n'inclut PAS la date
// (la page la rend déjà). Le slot est ajouté en post-traitement, donc
// Gemini ne doit PAS le préfixer lui-même.
const prompt = `Tu rédiges un mini-récap éditorial sur le sujet "${topic.label}" pour le hub patch-notes.fr.
Public : lecteur curieux, 30 secondes de lecture.

TITRE
- 50 à 90 caractères, sans préfixe, sans date, sans nom de média.
- Style "bandeau de news" : sujet + verbe d'action + détail concret.
- Cite 1 ou 2 protagonistes nommés (équipe, joueur, jeu, éditeur, événement, plateforme).
- Interdits en début de titre : "Récap", "Veille", "Radar", "Le journal", "Top", "Le point", "Brèves".
- Interdits dans le titre : émojis, dates, "—", "/", majuscules abusives.

RÉSUMÉ
- 2 à 3 phrases courtes, 40 à 80 mots au total. Style journaliste, pas administratif.
- Phrase 1 = la news la plus marquante de la liste, formulée nettement (sujet + action + contexte).
- Phrase 2 = un autre signal fort de la liste, complémentaire.
- Phrase 3 (optionnelle) = une perspective courte, un calendrier ou un point à surveiller.
- Cite des entités concrètes : équipe, joueur, jeu, éditeur, événement, plateforme, étude.
- INTERDITS dans le résumé :
  • "France : X articles", "International : X articles", "Articles : X retenus".
  • "Sources à vérifier", "aucun article retenu", noms de médias listés à la suite.
  • "À retenir :", "À suivre :", "Côté FR :", "Côté international :", "Pour résumer", "Dans cet article", "On apprend que".
  • Émojis, markdown, balises HTML, listes à puces.
- ${styleGuide}

CONTRAINTES TECHNIQUES
- Réponds uniquement en JSON valide : {"title":"...","summary":"..."}.
- N'invente rien : ne mentionne que des éléments présents dans la liste ci-dessous.
${topic.editorialHints ? `\nPRÉCISIONS SPÉCIFIQUES AU SUJET :\n${topic.editorialHints}\n` : ''}
ARTICLES DISPONIBLES (du plus récent au plus ancien) :
${articleLines || '(aucun article — renvoie {"title":"' + fallbackTitle.replace(/"/g, '\\"') + '","summary":"' + fallbackSummary.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"})'}`;

return [
  {
    json: {
      secret: config.blog?.secret,
      fallbackTitle,
      fallbackSummary,
      recapDate,
      geminiModel: config.gemini?.model || 'gemini-2.5-flash',
      geminiApiKey: config.gemini?.apiKey || '',
      geminiRequest: {
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        generationConfig: {
          temperature: 0.4,
          maxOutputTokens: 420,
          responseMimeType: 'application/json',
          thinkingConfig: { thinkingBudget: 0 }
        }
      },
      postBase: {
        id: `${topic.slug}-${topic.mode}-${now.toISOString().slice(0, 13)}`,
        topic: topic.slug,
        topicLabel: topic.label,
        topicDescription: topic.description || null,
        slot,
        title: fallbackTitle,
        summary: fallbackSummary,
        mode: topic.mode,
        sourceGroups,
        errors,
        debug: {
          loadedArticlesCount: loadedArticles.length,
          uniqueArticlesBeforeSameDayFilter: seen.size,
          skippedInvalidUrl,
          skippedDuplicate,
          skippedSameDay,
          selectedArticlesCount: selectedArticles.length
        },
        articles: selectedArticles,
        createdAt: now.toISOString()
      }
    }
  }
];

// ============================================================================
// 4. Finaliser le post (auto)
// ----------------------------------------------------------------------------
// Lit la sortie Gemini (si on est passés par lui) et reconstruit le post final.
// Si Gemini est absent (rate-limited, clé manquante, parsing KO), on garde le
// titre/summary fallback déjà préparés en amont.
//
// On nettoie aussi tout résidu administratif dans le résumé : si Gemini ignore
// la consigne et écrit malgré tout "France : 7 articles..." ou "Sources à
// vérifier", on retire ces phrases avant publication. Filet de sécurité.
// ============================================================================

function parseGeminiJson(text) {
  const cleaned = String(text || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  try {
    return JSON.parse(cleaned);
  } catch {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try {
      return JSON.parse(match[0]);
    } catch {
      return null;
    }
  }
}

// On retire les phrases entières qui contiennent un marqueur "admin" plutôt
// que d'essayer un replace ciblé : ça évite les ratés quand le texte contient
// des points (ex. "Mandatory.gg") qui cassent un regex `[^.]*`.
const ADMIN_SENTENCE_MARKERS = [
  /\bFrance\s*:\s*\d+\s*articles?/i,
  /\bInternational\s*:\s*\d+\s*articles?/i,
  /\bArticles?\s*:\s*\d+\s*retenus?/i,
  /\bSources?\s+à\s+v[eé]rifier/i,
  /\baucun\s+article\b.*\bretenu/i,
  /\bÀ\s+suivre\s+côté\s+FR/i,
  /\bC[ôo]t[eé]\s+international\s*:/i,
  /\bPour\s+résumer\b/i,
  /\bDans\s+cet\s+article\b/i,
  /\bOn\s+apprend\s+que\b/i
];

function sanitizeSummary(summary) {
  if (!summary) return '';
  const sentences = String(summary).split(/(?<=[.!?])\s+/);
  const kept = sentences.filter(
    (sentence) => !ADMIN_SENTENCE_MARKERS.some((re) => re.test(sentence))
  );
  return kept.join(' ').replace(/\s{2,}/g, ' ').replace(/\s+([.,;:])/g, '$1').trim();
}

const TITLE_BAD_PREFIXES = /^(R[eé]cap|Veille|Radar|Le\s+journal|Top\s*\d*|Le\s+point|Br[eè]ves)\b[^a-zA-Z0-9]*/i;

// On force le slot en préfixe et on nettoie les préfixes éditoriaux mous
// que Gemini aime parfois ajouter ("Récap : ...", "Le point : ..."). On retire
// aussi la date si Gemini l'a glissée dedans malgré l'interdiction.
function buildFinalTitle(generatedTitle, slot, recapDate) {
  let title = String(generatedTitle || '').trim();
  if (slot && title.startsWith(`${slot} - `)) title = title.slice(slot.length + 3).trim();
  title = title.replace(TITLE_BAD_PREFIXES, '').trim();
  if (recapDate) {
    title = title.replace(new RegExp(`\\s*-?\\s*${recapDate.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*$`, 'i'), '').trim();
  }
  if (!title) title = '';
  return slot ? `${slot} - ${title}`.trim().replace(/\s*-\s*$/, '').trim() : title;
}

const base = $items('Assembler recap')[0].json;
const incoming = $input.first()?.json || {};
const post = { ...base.postBase };

if (!post.articles?.length) {
  post.title = base.fallbackTitle;
  post.summary = base.fallbackSummary;
  return [{ json: { secret: base.secret, post } }];
}

const text = incoming?.candidates?.[0]?.content?.parts
  ?.map((part) => part.text || '')
  .join(' ')
  .trim();
const parsed = parseGeminiJson(text);

if (parsed?.title || parsed?.summary) {
  const generatedTitle = String(parsed.title || base.fallbackTitle).trim();
  const finalTitle = buildFinalTitle(generatedTitle, post.slot, base.recapDate);
  post.title = finalTitle || base.fallbackTitle;

  const generatedSummary = String(parsed.summary || base.fallbackSummary).trim();
  const sanitized = sanitizeSummary(generatedSummary);
  // Si tout le résumé Gemini était admin, on retombe sur le fallback éditorial.
  post.summary = sanitized.length >= 30 ? sanitized : base.fallbackSummary;
} else if (incoming?.error?.message) {
  post.errors = [...(post.errors || []), `Gemini: ${incoming.error.message}`];
}

return [{ json: { secret: base.secret, post } }];
